def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()

def run(*args: str) -> subprocess.CompletedProcess[str]:
    return subprocess.run(args, text=True, capture_output=True, check=False)

def fail(message: str) -> None:
    print(f"[FAIL] {message}", file=sys.stderr)
    raise SystemExit(1)

def main() -> None:
    root = Path.cwd()
    git_check = run("git", "rev-parse", "--show-toplevel")
    if git_check.returncode != 0:
        fail("Run this patch from inside the repository root: " + git_check.stderr.strip())
    repo_root = Path(git_check.stdout.strip()).resolve()
    if root.resolve() != repo_root:
        fail(f"Run from the repository root exactly: {repo_root}")

    current: dict[str, str] = {}
    for rel in EXPECTED_BEFORE:
        path = root / rel
        if not path.is_file():
            fail(f"Missing target file: {rel}")
        current[rel] = sha256(path)

    if all(current[rel] == EXPECTED_AFTER[rel] for rel in current):
        print(f"[OK] {PATCH_NAME} is already applied.")
        return

    drift = [f"{rel} expected={EXPECTED_BEFORE[rel]} actual={current[rel]}" for rel in current if current[rel] != EXPECTED_BEFORE[rel]]
    if drift:
        fail("Baseline drift detected; nothing was changed. " + " | ".join(drift))

    with tempfile.NamedTemporaryFile("w", suffix=".diff", encoding="utf-8", newline="\n", delete=False) as handle:
        handle.write(PATCH)
        patch_path = Path(handle.name)
    try:
        check = run("git", "apply", "--check", "--whitespace=error-all", str(patch_path))
        if check.returncode != 0:
            fail("git apply --check rejected the patch; nothing was changed. " + (check.stderr or check.stdout).strip())

        applied = run("git", "apply", "--whitespace=error-all", str(patch_path))
        if applied.returncode != 0:
            fail("git apply failed. " + (applied.stderr or applied.stdout).strip())

        bad_after = []
        for rel, expected in EXPECTED_AFTER.items():
            actual = sha256(root / rel)
            if actual != expected:
                bad_after.append(f"{rel} expected={expected} actual={actual}")
        if bad_after:
            reverse = run("git", "apply", "-R", str(patch_path))
            suffix = "" if reverse.returncode == 0 else " Automatic rollback also failed; inspect git diff immediately."
            fail("Post-patch hash verification failed. " + " | ".join(bad_after) + suffix)

        print(f"[PASS] {PATCH_NAME}")
        for rel in EXPECTED_AFTER:
            print(f"  {EXPECTED_AFTER[rel]}  {rel}")
        print("Next: run backend compile/tests and dashboard build before commit.")
    finally:
        try:
            patch_path.unlink()
        except OSError:
            pass

if __name__ == "__main__":
    main()
